        container,
        children,
        open,
        disableBodyScrollLock = false,
        disableEscapeKeyDown = false,
        disableOutsideClick = false,
        initialFocus,
        returnFocus,
        keepMounted = false,
        size,
        contentOverflow = 'visible',
        className,
        modalClassName,
        hasCloseButton = true,
        disableHeightTransition = false,
        onEscapeKeyDown,
        onEnterKeyDown,
        onOpenChange,
        onOutsideClick,
